package com.wedo.backend.journey;
import static com.wedo.backend.journey.JourneyDtos.*;
import com.wedo.backend.activity.service.*;
import com.wedo.backend.activity.entity.ActivityStatus;
import com.wedo.backend.common.error.*;
import com.wedo.backend.group.entity.GroupRole;
import com.wedo.backend.moment.*;
import com.wedo.backend.media.dto.UploadCategory;
import com.wedo.backend.media.service.MediaReferenceService;
import com.wedo.backend.realtime.RealtimePublisher;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true)
public class JourneyService {
 final JdbcTemplate db;final M8ActivityAccessService access;final MomentService moments;final RealtimePublisher events;final MediaReferenceService refs;
 public JourneyService(JdbcTemplate db,M8ActivityAccessService access,MomentService moments,RealtimePublisher events,MediaReferenceService refs){this.db=db;this.access=access;this.moments=moments;this.events=events;this.refs=refs;}
 BusinessException invalid(){return new BusinessException(ErrorCode.VALIDATION_FAILED);} BusinessException denied(){return new BusinessException(ErrorCode.ACCESS_DENIED);} BusinessException missing(){return new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);}
 M8ActivityAccess readable(UUID activity,UUID actor){var a=access.requireReadable(activity,actor);if(Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM group_bans WHERE group_id=? AND user_id=? AND unbanned_at IS NULL)",Boolean.class,a.activity().getGroupId(),actor)))throw denied();return a;}
 M8ActivityAccess mutable(UUID activity,UUID actor){access.requireLocked(activity);var a=readable(activity,actor);access.requireMutable(activity,actor);if(Set.of(ActivityStatus.COMPLETED,ActivityStatus.CANCELLED).contains(a.activity().getStatus()))throw new BusinessException(ErrorCode.ACTIVITY_CLOSED);return a;}
 boolean manager(M8ActivityAccess a,UUID actor){return actor.equals(a.activity().getCreatedBy())||a.groupAccess().membership().getRole()!=GroupRole.MEMBER;}
 void requireManager(M8ActivityAccess a,UUID actor){if(!manager(a,actor))throw denied();}
 Map<String,Object> row(UUID activity,UUID stop){var rows=db.queryForList("SELECT * FROM activity_stops WHERE id=? AND activity_id=? AND deleted_at IS NULL",stop,activity);if(rows.isEmpty())throw missing();return rows.getFirst();}
 Timestamp ts(Instant value){return value==null?null:Timestamp.from(value);}
 Instant at(Map<String,Object> r,String key){return r.get(key)==null?null:((Timestamp)r.get(key)).toInstant();}
 boolean active(Map<String,Object> r){return Set.of("PLANNED","IN_PROGRESS").contains(r.get("status"));}
 void current(Map<String,Object> r,Instant expected){if(expected==null||!expected.equals(at(r,"updated_at")))throw new BusinessException(ErrorCode.CONFLICT);}
 void emit(String type,UUID id,M8ActivityAccess a){events.activityResource(type,"ACTIVITY_STOP",id,a.activity().getId(),a.activity().getGroupId(),null);}
 Stop view(Map<String,Object> r,M8ActivityAccess a,UUID actor){UUID id=(UUID)r.get("id"),organizer=(UUID)r.get("organizer_id");boolean writable=a.groupAccess().group().getStatus()==com.wedo.backend.group.entity.GroupStatus.ACTIVE&&!Set.of(ActivityStatus.CANCELLED,ActivityStatus.COMPLETED).contains(a.activity().getStatus());boolean manage=writable&&manager(a,actor);String name=organizer==null?null:db.queryForObject("SELECT COALESCE(display_name,username::text) FROM users WHERE id=?",String.class,organizer);return new Stop(id,a.activity().getId(),(String)r.get("title"),(String)r.get("notes"),at(r,"starts_at"),at(r,"ends_at"),(String)r.get("location_label"),organizer,name,(java.math.BigDecimal)r.get("estimated_cost"),(Integer)r.get("sort_order"),Status.valueOf((String)r.get("status")),at(r,"updated_at"),db.queryForObject("SELECT count(*) FROM activity_stop_checkins c JOIN group_moments m ON m.id=c.moment_id WHERE c.stop_id=? AND m.deleted_at IS NULL",Long.class,id),manage, writable&&active(r)&&(manage||actor.equals(organizer)),writable&&active(r));}
 public Journey journey(UUID activity,UUID actor){var a=readable(activity,actor);return new Journey(activity,a.activity().getGroupId(),a.activity().getTitle(),manager(a,actor)&&a.groupAccess().group().getStatus()==com.wedo.backend.group.entity.GroupStatus.ACTIVE&&!Set.of(ActivityStatus.CANCELLED,ActivityStatus.COMPLETED).contains(a.activity().getStatus()),db.queryForList("SELECT * FROM activity_stops WHERE activity_id=? AND deleted_at IS NULL ORDER BY sort_order,id",activity).stream().map(r->view(r,a,actor)).toList());}
 public Stop get(UUID activity,UUID stop,UUID actor){return view(row(activity,stop),readable(activity,actor),actor);}
 void validate(Save r,M8ActivityAccess a){if(r.endsAt()!=null&&!r.endsAt().isAfter(r.startsAt()))throw invalid();if(a.activity().getStartAt()!=null&&r.startsAt().isBefore(a.activity().getStartAt()))throw invalid();if(a.activity().getEndAt()!=null&&(r.startsAt().isAfter(a.activity().getEndAt())||(r.endsAt()!=null&&r.endsAt().isAfter(a.activity().getEndAt()))))throw invalid();if(r.organizerId()!=null&&!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM group_memberships m WHERE m.group_id=? AND m.user_id=? AND m.status='ACTIVE' AND NOT EXISTS(SELECT 1 FROM group_bans b WHERE b.group_id=m.group_id AND b.user_id=m.user_id AND b.unbanned_at IS NULL))",Boolean.class,a.activity().getGroupId(),r.organizerId())))throw denied();}
 @Transactional public Stop create(UUID activity,UUID actor,Save r){var a=mutable(activity,actor);requireManager(a,actor);validate(r,a);var old=db.queryForList("SELECT activity_id,created_by FROM activity_stops WHERE id=?",r.clientRequestId());if(!old.isEmpty()){if(!activity.equals(old.getFirst().get("activity_id"))||!actor.equals(old.getFirst().get("created_by")))throw invalid();return get(activity,r.clientRequestId(),actor);}if(db.queryForObject("SELECT count(*) FROM activity_stops WHERE activity_id=? AND deleted_at IS NULL",Integer.class,activity)>=200)throw invalid();int order=db.queryForObject("SELECT COALESCE(max(sort_order),-1)+1 FROM activity_stops WHERE activity_id=? AND deleted_at IS NULL",Integer.class,activity);db.update("INSERT INTO activity_stops(id,activity_id,title,notes,starts_at,ends_at,location_label,organizer_id,estimated_cost,sort_order,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?)",r.clientRequestId(),activity,r.title().trim(),r.notes().trim(),ts(r.startsAt()),ts(r.endsAt()),r.locationLabel().trim(),r.organizerId(),r.estimatedCost(),order,actor);emit("ACTIVITY_STOP_CREATED",r.clientRequestId(),a);return get(activity,r.clientRequestId(),actor);}
 @Transactional public Stop edit(UUID activity,UUID stop,UUID actor,Save r){var a=mutable(activity,actor);requireManager(a,actor);var old=row(activity,stop);current(old,r.expectedUpdatedAt());if(!active(old))throw invalid();validate(r,a);db.update("UPDATE activity_stops SET title=?,notes=?,starts_at=?,ends_at=?,location_label=?,organizer_id=?,estimated_cost=?,updated_at=clock_timestamp() WHERE id=?",r.title().trim(),r.notes().trim(),ts(r.startsAt()),ts(r.endsAt()),r.locationLabel().trim(),r.organizerId(),r.estimatedCost(),stop);emit("ACTIVITY_STOP_UPDATED",stop,a);return get(activity,stop,actor);}
 @Transactional public Stop state(UUID activity,UUID stop,UUID actor,State r){var a=mutable(activity,actor);var old=row(activity,stop);current(old,r.expectedUpdatedAt());if(!manager(a,actor)&&!actor.equals(old.get("organizer_id")))throw denied();if(!r.status().name().equals(old.get("status"))&&(!active(old)||r.status()==Status.PLANNED))throw invalid();db.update("UPDATE activity_stops SET status=?,updated_at=clock_timestamp() WHERE id=?",r.status().name(),stop);emit("ACTIVITY_STOP_STATUS_CHANGED",stop,a);return get(activity,stop,actor);}
 @Transactional public void delete(UUID activity,UUID stop,UUID actor,Instant expected){var a=mutable(activity,actor);requireManager(a,actor);current(row(activity,stop),expected);db.update("UPDATE activity_stops SET deleted_at=clock_timestamp(),updated_at=clock_timestamp() WHERE id=?",stop);emit("ACTIVITY_STOP_DELETED",stop,a);}
 @Transactional public Journey reorder(UUID activity,UUID actor,Reorder r){var a=mutable(activity,actor);requireManager(a,actor);var ids=db.queryForList("SELECT id FROM activity_stops WHERE activity_id=? AND deleted_at IS NULL ORDER BY sort_order,id",UUID.class,activity);if(ids.equals(r.orderedIds()))return journey(activity,actor);if(!ids.equals(r.expectedOrder())||r.orderedIds().size()!=ids.size()||!new HashSet<>(ids).equals(new HashSet<>(r.orderedIds())))throw new BusinessException(ErrorCode.CONFLICT);db.update("UPDATE activity_stops SET sort_order=sort_order+1000000 WHERE activity_id=? AND deleted_at IS NULL",activity);int n=0;for(UUID id:r.orderedIds())db.update("UPDATE activity_stops SET sort_order=?,updated_at=clock_timestamp() WHERE id=?",n++,id);emit("ACTIVITY_STOP_REORDERED",activity,a);return journey(activity,actor);}
 CheckInView check(UUID id,UUID actor){var r=db.queryForMap("SELECT * FROM activity_stop_checkins WHERE moment_id=?",id);return new CheckInView((UUID)r.get("stop_id"),(String)r.get("source"),at(r,"client_captured_at"),at(r,"received_at"),moments.get(id,actor));}
 @Transactional public CheckInView checkIn(UUID activity,UUID stop,UUID actor,CheckIn r){var a=mutable(activity,actor);var parent=row(activity,stop);var old=db.queryForList("SELECT c.stop_id,m.created_by FROM activity_stop_checkins c JOIN group_moments m ON m.id=c.moment_id WHERE c.moment_id=?",r.clientRequestId());if(!old.isEmpty()){if(!stop.equals(old.getFirst().get("stop_id"))||!actor.equals(old.getFirst().get("created_by")))throw invalid();return check(r.clientRequestId(),actor);}if(!active(parent))throw invalid();for(String key:r.mediaKeys()){var parsed=refs.parse(key);if(parsed==null||parsed.category()!=UploadCategory.MOMENT_IMAGE)throw invalid();}
  moments.create(a.activity().getGroupId(),actor,new MomentDtos.CreateMoment(r.clientRequestId(),activity,r.caption(),r.mediaKeys()));db.update("INSERT INTO activity_stop_checkins(moment_id,stop_id,source,client_captured_at) VALUES (?,?,'CAMERA_CLIENT_DECLARED',?)",r.clientRequestId(),stop,ts(r.clientCapturedAt()));emit("ACTIVITY_STOP_CHECKIN_CREATED",stop,a);return check(r.clientRequestId(),actor);}
 public MomentDtos.Page<CheckInView> checkIns(UUID activity,UUID stop,UUID actor,UUID before){readable(activity,actor);row(activity,stop);var ids=db.queryForList("SELECT c.moment_id FROM activity_stop_checkins c JOIN group_moments m ON m.id=c.moment_id AND m.deleted_at IS NULL WHERE c.stop_id=? AND (?::uuid IS NULL OR (c.received_at,c.moment_id)<(SELECT received_at,moment_id FROM activity_stop_checkins WHERE moment_id=? AND stop_id=?)) ORDER BY c.received_at DESC,c.moment_id DESC LIMIT 21",UUID.class,stop,before,before,stop);return new MomentDtos.Page<>(ids.stream().limit(20).map(id->check(id,actor)).toList(),ids.size()>20?ids.get(19):null,ids.size()>20);}
}
